"""Explain argument names, list commas, template priority and documentation generation."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1577': ('“종류:이름”이라고 쓴 명찰에서 이름만 떼어 보세요. 종류를 고르는 일과 부를 이름을 고르는 일은 다른 단계예요.', '인자 명세에서 타입과 이름을 따로 꺼내는 규칙을 이해합니다.', 'cv → v, i:new → new, p:old → old를 적으세요. i:old와 p:old는 이름이 둘 다 old지만 타입은 long과 long *로 다르다고 표시하세요.', ['gen_param_name은 인자의 이름을 만드는 쉘 함수예요. 인자는 함수를 부를 때 건네는 정보예요. 이 함수는 숫자를 계산하지 않고 C 코드에 쓸 이름 글자를 출력해요.', '첫 줄의 ${1#c}는 첫 입력 맨 앞에 c가 있으면 그 c를 떼어요. 그래서 cv는 v가 돼요. 앞에 c가 없는 i:new는 이 단계에서 그대로 남아요. 중간의 c까지 모두 지우는 규칙은 아니에요.', '다음 ${name#*:}는 콜론까지의 앞부분을 떼어 뒤의 이름을 남겨요. 여기의 #는 맞는 가장 짧은 앞부분을 제거하는 쉘 문법이에요. i:new는 new, p:old는 old가 돼요. cv에서 만든 v처럼 콜론이 없으면 그대로 v예요.', '타입은 gen_param_type이 따로 골라요. 그 함수의 ${1%%:*}는 콜론부터 뒤쪽을 떼어 타입 표시를 얻어요. p:old라면 p가 남고 기본 정수가 long일 때 long *를 만들어요.', 'gen_param은 이렇게 만든 타입과 이름을 붙여요. p:old는 long *old, i:old는 long old가 될 수 있어요. 이름 old는 같지만 앞의 타입 때문에 위치를 받는지 값 자체를 받는지가 달라요.', 'cv에서 이름의 c를 뺐다고 타입의 const 제한까지 없애는 것은 아니에요. 타입 계산에는 원래 명세 cv를 넘기므로 const atomic_long_t *v 같은 선언을 만들어요. 이 코드는 쉘 문자열 처리이며 #나 *를 C의 포인터·계산 기호로 읽으면 안 돼요.'], [('gen_param_name에 cv를 넘기면 기본 인자 이름은 무엇인가요?', ['cv 전체예요', '앞의 c를 뺀 v예요'], '정답은 두 번째예요. 먼저 ${1#c}로 앞 c를 빼고, 콜론이 없으므로 v를 그대로 출력해요. 이름에서 c를 빼도 타입의 const 설명까지 없애는 것은 아니에요.'), ('i:new에서 출력되는 인자 이름은 무엇인가요?', ['콜론 뒤의 new예요', '타입 표시까지 포함한 i:new예요'], '정답은 첫 번째예요. i는 타입을 고르는 정보이고 new는 이름이에요. 타입과 이름을 따로 만든 뒤 C 선언에 합쳐요.')]), 'os1578': ('물건 목록을 적을 때 “연필, 지우개, 자”처럼 사이에만 쉼표를 써요. 생성기도 인자를 하나씩 꺼내고 다음 것이 있을 때만 쉼표를 붙여요.', '선언 목록과 호출 목록, shift에 따른 남은 인자 수를 이해합니다.', 'v p:old i:new에서 선언 “atomic_long_t *v, long *old, long new”와 호출 “v, old, new”를 나란히 적으세요.', ['gen_params는 함수 선언에 필요한 타입과 이름 목록을 만들어요. 처음 받은 기본 정수 이름 long과 원자 계열 이름 atomic_long은 설정으로 저장하고, 실제 인자 명세를 처리할 차례로 넘어가요.', '쉘의 $1은 현재 첫 인자, $#는 남은 인자 개수예요. shift를 한 번 하면 첫 인자를 처리 목록에서 빼고 다음 인자가 새 $1이 돼요. 여기서는 숫자의 비트를 미는 연산이 아니라 위치 인자 목록을 옮기는 명령이에요.', '반복문은 인자가 남아 있는 동안 첫 인자로 gen_param을 불러 타입과 이름을 출력해요. v, p:old, i:new라면 차례로 atomic_long_t *v, long *old, long new를 만들어요.', '각 항목을 출력한 뒤 $#가 1보다 큰지 확인해요. 현재를 포함해 둘 이상 남았으면 다음 항목이 있다는 뜻이라 쉼표와 공백을 찍어요. 그다음 shift해요. 개수가 3·2·1일 때 쉼표는 앞의 두 차례에만 나와요.', 'gen_args는 같은 명세에서 이름만 출력해 v, old, new를 만들어요. 선언에는 무엇을 받는지 알려 주는 타입이 필요하고, 호출에는 전달할 이름들이 필요하기 때문이에요. 같은 명세를 쓰면 두 목록의 순서를 맞추기 쉬워요.', '둘 다 생성할 코드의 글자를 만드는 도구예요. old의 실제 숫자를 읽거나 원자 연산을 실행하는 것은 아니에요. 마지막 쉼표가 없는 것도 C가 아무 쉼표나 허용해서가 아니라 생성기가 남은 개수를 확인하기 때문이에요.'], [('gen_params와 gen_args가 만드는 목록의 차이는 무엇인가요?', ['둘 다 실제 숫자를 계산해 저장해요', '선언용은 타입과 이름, 호출용은 이름 목록을 만들어요'], '정답은 두 번째예요. 같은 명세에서 long *old 같은 선언과 old 같은 호출 인자를 따로 만들어요. 아직 원자 연산의 숫자를 계산하는 단계가 아니에요.'), ('생성기는 마지막 인자 뒤에도 항상 쉼표를 붙이나요?', ['아니요. 현재를 포함해 인자가 둘 이상 남았을 때만 붙여요', '네. C에서는 어느 위치에 쉼표가 있어도 괜찮아요'], '정답은 첫 번째예요. $#가 1보다 큰지 확인한 다음 shift해요. 마지막에는 개수가 1이므로 쉼표를 찍지 않아요.')]), 'os1579': ('특정 행사 전용 양식이 있으면 그것을 쓰고, 없으면 일반 양식을 찾아요. 생성기도 가장 구체적인 이름부터 차례로 찾아 첫 양식 하나를 골라요.', '템플릿 검색의 우선순위와 아무것도 찾지 못한 경우를 이해합니다.', 'fetch_add_acquire → fetch_add → add를 그리세요. 첫 파일이 있으면 거기서 멈추고, 없을 때만 다음 후보로 간다고 표시하세요.', ['템플릿은 빈칸을 채워 코드를 만들 때 쓰는 양식이에요. find_template은 양식 파일의 위치를 찾는 함수예요. 찾는 것과 그 파일 내용을 읽어 코드를 생성하는 일은 다른 단계예요.', '먼저 앞이름·기본이름·뒷이름·순서이름을 모두 합친 가장 구체적인 후보를 봐요. 예를 들어 앞이름 fetch_, 기본이름 add, 순서이름 _acquire라면 fetch_add_acquire예요.', '그 파일이 없으면 순서이름을 뺀 fetch_add를 보고, 그것도 없으면 기본이름 add를 봐요. 전용 양식이 일반 양식보다 앞서는 순서예요. 후보마다 -f 검사로 일반 파일이 있는지 확인해요.', '처음 파일을 찾으면 printf로 그 경로를 출력하고 break로 반복을 끝내요. 여러 후보가 있어도 모두 이어 붙이는 것이 아니에요. 첫 후보와 add가 함께 있으면 첫 후보를 선택해요.', '아무 후보도 없으면 printf를 실행하지 않으므로 경로 출력은 비어 있어요. 존재하지 않는 마지막 후보를 억지로 출력하지 않아요. 호출하는 쪽은 빈 결과를 받았을 때의 처리를 따로 해야 해요.', 'fallback용과 kerneldoc용 도우미는 같은 검색 함수에 다른 하위 폴더를 넘겨요. 하나는 대체 구현 양식, 다른 하나는 문서 양식을 찾는 데 써요. 연습할 때는 실제 파일을 지우기보다 종이에 각 후보의 있음·없음을 표시해 선택을 따라가세요.'], [('fetch_add_acquire 전용 파일과 일반 add 파일이 모두 있으면 무엇을 선택하나요?', ['항상 일반 add를 먼저 선택해요', '더 구체적인 fetch_add_acquire를 선택해요'], '정답은 두 번째예요. 가장 구체적인 후보부터 검사하고 첫 파일을 찾으면 멈춰요. 일반 파일까지 함께 합치는 규칙은 아니에요.'), ('후보 파일이 하나도 없으면 경로 출력은 어떻게 되나요?', ['아무 경로도 출력하지 않아요', '존재하지 않아도 마지막 일반 경로를 출력해요'], '정답은 첫 번째예요. -f 검사를 통과한 갈래에만 printf가 있어요. 따라서 호출자는 비어 있는 결과를 처리해야 해요.')]), 'os1580': ('설명서에 “이 작업은 이런 순서를 지킵니다”라고 적는 것과 실제로 그 순서를 지키는 장치를 만드는 것은 달라요. 생성되는 주석과 실행 코드를 나누어 읽어 봅시다.', '문서의 순서 단어 선택 규칙과 실제 메모리 장벽을 구별합니다.', '명시 _acquire → acquire, 이름 없는 meta v → relaxed, 이름 없는 meta F → full의 세 갈래를 적으세요.', ['gen_template_kerneldoc은 함수 이름, 반환 타입, 인자와 설명 문구를 준비해 문서 양식을 채워요. kerneldoc은 커널 코드에 붙는 설명 주석이라고 생각하면 돼요.', 'order에 _acquire 같은 명시적 이름이 있으면 앞 밑줄을 떼고 acquire라는 설명을 골라요. _release이면 release, _relaxed이면 relaxed예요. 가장 먼저 이 명시된 이름을 확인해요.', '명시된 이름이 없으면 meta_is_implicitly_relaxed를 확인해요. v·l·s가 이 분류에 속하므로 반환 없는 연산, 기본 읽기, 기본 저장에는 relaxed 설명을 골라요. 이름에 꼬리표가 없다고 모두 full이라고 판단하면 안 돼요.', '앞 조건들에 해당하지 않으면 full을 골라요. 예를 들어 기본 fetch_add의 F는 여기로 와요. 이 기본 설명만으로 조건부 함수의 실패 경로까지 모두 full이라고 일반화하면 안 돼요. 함수별 문서 양식의 성공·실패 설명도 함께 읽어야 해요.', 'class가 비었는지에 따라 계측을 허용하지 않는 noinstr 영역의 사용 안내도 달라져요. 일반 API에는 그 영역에서 raw를 쓰라는 안내, raw API에는 다른 일반 영역에서는 일반 API를 선호하라는 안내를 준비해요. 마지막에 문서 템플릿을 읽어 설명을 출력해요.', '출력된 full이나 acquire라는 주석 단어 자체가 CPU 장벽 명령은 아니에요. 주석은 구현이 지켜야 할 약속을 설명해요. 생성된 함수의 호출 경로와 실제 구현이 그 약속에 맞는지도 확인해야 해요. 설명을 출력하는 단계와 실행 단계는 달라요.'], [('명시적인 순서 꼬리표가 없는 meta v의 기본 문서 설명은 무엇인가요?', ['꼬리표가 없으므로 항상 full이에요', 'v가 기본 relaxed 분류에 있어 relaxed예요'], '정답은 두 번째예요. 생성기는 v·l·s를 따로 검사해 relaxed 설명을 골라요. 기본 형태라고 모두 같은 순서 약속은 아니에요.'), ('문서 생성기가 ordering 단어를 출력하면 그때 CPU의 장벽도 실행되나요?', ['아니요. 출력은 설명 주석이며 실제 장벽 실행과 달라요', '네. 주석의 full이라는 단어가 CPU 명령이에요'], '정답은 첫 번째예요. 설명서는 약속을 적고 실제 구현은 그 약속을 지켜야 해요. 주석을 만들었다고 실행 중 접근 순서가 저절로 보장되지는 않아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_390.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
